SELECT * FROM quality_agent
WHERE is_deleted = 0

    AND agent_name LIKE CONCAT('%', #{agentName}, '%')

AND agent_type = #{agentType}
AND status = #{status}
ORDER BY id DESC

mapper.update:
UPDATE quality_agent
updated_at = NOW(), agent_name = #{agentName}, agent_type = #{agentType}, endpoint_url = #{endpointUrl}, auth_token = #{authToken}, remark = #{remark}, updated_by = #{updatedBy}
WHERE id = #{id} AND is_deleted = 0
